"""Migration of Meridian CRM 4.2 CRMScript numeric division semantics."""


def _legacy_number(value) -> float:
    """Apply legacy numeric-context coercion for supported operand values."""
    if value is None or value == "":
        return 0.0
    try:
        return float(value)
    except (TypeError, ValueError, OverflowError):
        return 0.0


def safe_div(a, b) -> tuple[float, list[str]]:
    """Divide using legacy CRMScript division-by-zero behavior."""
    numerator = _legacy_number(a)
    divisor = _legacy_number(b)

    if divisor == 0.0:
        return 0.0, ["SCRIPT_DIV0"]

    try:
        return numerator / divisor, []
    except (ArithmeticError, OverflowError):
        return 0.0, []
